mapper.select:
SELECT a.id, a.handle_id, a.user_id, a.nickname, a.type, a.process, a.status, a.round_no, a.create_date, a.update_date, r.role_name AS roleName FROM dz_task_handle_approval a LEFT JOIN (SELECT user_id, MIN(role_id) AS role_id FROM sys_user_role GROUP BY user_id) ur ON a.user_id = ur.user_id LEFT JOIN (SELECT role_id, MIN(role_name) AS role_name FROM sys_role GROUP BY role_id) r ON ur.role_id = r.role_id WHERE a.handle_id = #{handleId} AND a.type = 1 AND a.status = 1
AND a.round_no = #{roundNo}
ORDER BY a.create_date DESC, a.id DESC LIMIT 1

SELECT a.id, a.handle_id, a.user_id, a.nickname, a.type, a.process, a.status, a.round_no, a.create_date, a.update_date, r.role_name AS roleName FROM dz_task_handle_approval a LEFT JOIN (SELECT user_id, MIN(role_id) AS role_id FROM sys_user_role GROUP BY user_id) ur ON a.user_id = ur.user_id LEFT JOIN (SELECT role_id, MIN(role_name) AS role_name FROM sys_role GROUP BY role_id) r ON ur.role_id = r.role_id WHERE a.handle_id = #{handleId} AND a.type = 2
AND a.round_no = #{roundNo}
ORDER BY a.create_date ASC, a.id ASC
